	}

	for _, q := range in.QueryParameters {
		ir.queryParameters = append(ir.queryParameters, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_QueryParameter_{
				QueryParameter: &envoyroutev3.RouteAction_HashPolicy_QueryParameter{Name: q.Name},
			},
			Terminal: ptr.Deref(q.Terminal, false),
		})
	}

	for _, f := range in.FilterState {
		ir.filterState = append(ir.filterState, &envoyroutev3.RouteAction_HashPolicy{
			PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_FilterState_{
				FilterState: &envoyroutev3.RouteAction_HashPolicy_FilterState{Key: f.Key},
			},
			Terminal: ptr.Deref(f.Terminal, false),
		})
	}

	hasArrays := len(in.Headers) > 0 || len(in.Cookies) > 0 || len(in.QueryParameters) > 0 || len(in.FilterState) > 0
	switch {
	case in.SourceIP != nil:
		ir.sourceIP = sourceIPHashPolicy(ptr.Deref(in.SourceIP.Terminal, false))
	case !hasArrays:
		// default to hashing on the source IP when no hash policy is specified
		ir.sourceIP = sourceIPHashPolicy(false)
	}

	ir.finalize()
	out.consistentHash = ir
	return nil
}

func sourceIPHashPolicy(terminal bool) *envoyroutev3.RouteAction_HashPolicy {
	return &envoyroutev3.RouteAction_HashPolicy{
		PolicySpecifier: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_{
			ConnectionProperties: &envoyroutev3.RouteAction_HashPolicy_ConnectionProperties{SourceIp: true},
		},
		Terminal: terminal,
	}
}

// parseCookieTTL parses a cookie TTL expressed either as a Go duration string (e.g. "1h30m")
// or as an integer number of seconds (e.g. "3600").
func parseCookieTTL(s string) (time.Duration, error) {
	if secs, err := strconv.ParseInt(s, 10, 64); err == nil {
		if secs < 0 {
			return 0, fmt.Errorf("must not be negative: %q", s)
		}
		return time.Duration(secs) * time.Second, nil
	}
	d, err := time.ParseDuration(s)
	if err != nil {
		return 0, err
	}
	if d < 0 {
		return 0, fmt.Errorf("must not be negative: %q", s)
	}
	return d, nil
}

// finalize deduplicates each hash policy slice by its identifying key, keeping the first
// occurrence, and rebuilds hashPolicies in canonical type order.
func (c *consistentHashIR) finalize() {
	c.headers = dedupHashPolicies(c.headers)
	c.cookies = dedupHashPolicies(c.cookies)
	c.queryParameters = dedupHashPolicies(c.queryParameters)
	c.filterState = dedupHashPolicies(c.filterState)

	policies := slices.Concat(c.headers, c.cookies, c.queryParameters, c.filterState)
	if c.sourceIP != nil {
		policies = append(policies, c.sourceIP)
	}
	c.hashPolicies = policies
}

// hashPolicyKey returns the identifying key of a hash policy used for deduplication.
func hashPolicyKey(hp *envoyroutev3.RouteAction_HashPolicy) string {
	switch spec := hp.GetPolicySpecifier().(type) {
	case *envoyroutev3.RouteAction_HashPolicy_Header_:
		// HTTP header names are case-insensitive
		return "header/" + strings.ToLower(spec.Header.GetHeaderName())
	case *envoyroutev3.RouteAction_HashPolicy_Cookie_:
		return "cookie/" + spec.Cookie.GetName()
	case *envoyroutev3.RouteAction_HashPolicy_QueryParameter_:
		return "query/" + spec.QueryParameter.GetName()
	case *envoyroutev3.RouteAction_HashPolicy_FilterState_:
		return "filterState/" + spec.FilterState.GetKey()
	case *envoyroutev3.RouteAction_HashPolicy_ConnectionProperties_:
		return "sourceIp"
	default:
		return ""
	}
}

// dedupHashPolicies returns a new slice containing the first occurrence of each hash policy key.
func dedupHashPolicies(in []*envoyroutev3.RouteAction_HashPolicy) []*envoyroutev3.RouteAction_HashPolicy {
	if len(in) == 0 {
		return nil
	}
	seen := make(map[string]struct{}, len(in))
	out := make([]*envoyroutev3.RouteAction_HashPolicy, 0, len(in))
	for _, hp := range in {
		key := hashPolicyKey(hp)
		if _, ok := seen[key]; ok {
			continue
		}
		seen[key] = struct{}{}
		out = append(out, hp)
	}
	return out
}

// applyConsistentHash applies the consistent hash configuration to the Envoy route action.
func applyConsistentHash(consistentHash *consistentHashIR, action *envoyroutev3.RouteAction) {
	if consistentHash == nil || action == nil {
		return
	}
	if consistentHash.disable {
		action.HashPolicy = nil
		return
	}
	action.HashPolicy = consistentHash.hashPolicies
}

// mergeConsistentHash unions the hash policies of p1 and p2, giving precedence to the higher
// priority policy as determined by the merge strategy. Array fields are concatenated with the
// higher priority policy's entries first and deduplicated by key, while the sourceIp scalar
// always retains the higher priority policy's value, even when unset.
func mergeConsistentHash(
	p1, p2 *TrafficPolicy,
	p2Ref *ir.AttachedPolicyRef,
	p2MergeOrigins ir.MergeOrigins,
	opts policy.MergeOptions,
	mergeOrigins ir.MergeOrigins,
	_ TrafficPolicyMergeOpts,
) {
	p1Field := p1.spec.consistentHash
	p2Field := p2.spec.consistentHash
	if p2Field == nil {
		return
	}
	if p1Field == nil {
		p1.spec.consistentHash = p2Field
		mergeOrigins.SetOne(consistentHashMergeField, p2Ref, p2MergeOrigins)
		return
	}

	var p2Preferred bool
	switch opts.Strategy {
	case policy.AugmentedShallowMerge, policy.AugmentedDeepMerge:
		p2Preferred = false
	case policy.OverridableShallowMerge, policy.OverridableDeepMerge:
		p2Preferred = true
	default:
		logger.Warn("unsupported merge strategy for policy", "strategy", opts.Strategy, "policy", p2Ref, "field", consistentHashMergeField)
		return
	}

	high, low := p1Field, p2Field
	if p2Preferred {
		high, low = p2Field, p1Field
	}

	// A disabled higher priority policy suppresses all hash policies, and a disabled lower
	// priority policy contributes nothing to the higher priority policy.
	if high.disable || low.disable {
		if p2Preferred {
			p1.spec.consistentHash = p2Field
			mergeOrigins.SetOne(consistentHashMergeField, p2Ref, p2MergeOrigins)
		}
		return
	}

	// Always build a new IR so that the original IRs are never modified
	merged := &consistentHashIR{
		headers:         slices.Concat(high.headers, low.headers),
		cookies:         slices.Concat(high.cookies, low.cookies),
		queryParameters: slices.Concat(high.queryParameters, low.queryParameters),
		filterState:     slices.Concat(high.filterState, low.filterState),
		sourceIP:        high.sourceIP,
	}
	merged.finalize()
	p1.spec.consistentHash = merged
	mergeOrigins.Append(consistentHashMergeField, p2Ref, p2MergeOrigins)
}

