			cookieHP("c"),
			queryHP("q"),
			filterStateHP("fs"),
			sourceIPHashPolicy(true),
		}, out.hashPolicies)
	})

	t.Run("header regex rewrite", func(t *testing.T) {
		out := constructConsistentHashForTest(t, &kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{{
				HeaderName:   "x-user",
				RegexRewrite: &kgateway.ConsistentHashRegexRewrite{Pattern: "^user-(.*)$", Substitution: `\1`},
			}},
		})
		require.Len(t, out.hashPolicies, 1)
		rewrite := out.hashPolicies[0].GetHeader().GetRegexRewrite()
		assert.Equal(t, "^user-(.*)$", rewrite.GetPattern().GetRegex())
		assert.Equal(t, `\1`, rewrite.GetSubstitution())
		assert.NoError(t, out.Validate())
	})

	t.Run("invalid header regex fails validation", func(t *testing.T) {
		out := constructConsistentHashForTest(t, &kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{{
				HeaderName:   "x-user",
				RegexRewrite: &kgateway.ConsistentHashRegexRewrite{Pattern: "(", Substitution: "x"},
			}},
		})
		assert.Error(t, out.Validate())
	})

	t.Run("cookie ttl and attributes", func(t *testing.T) {
		out := constructConsistentHashForTest(t, &kgateway.ConsistentHash{
			Cookies: []kgateway.ConsistentHashCookie{
				{
					Name:       "a",
					TTL:        ptr.To("1h30m"),
					Path:       ptr.To("/"),
					Attributes: []kgateway.ConsistentHashCookieAttribute{{Name: "SameSite", Value: "Lax"}, {Name: "Secure"}},
				},
				{Name: "b", TTL: ptr.To("3600")},
			},
		})
		require.Len(t, out.hashPolicies, 2)
		a := out.hashPolicies[0].GetCookie()
		assert.Equal(t, durationpb.New(90*time.Minute).AsDuration(), a.GetTtl().AsDuration())
		assert.Equal(t, "/", a.GetPath())
		require.Len(t, a.GetAttributes(), 2)
		assert.Equal(t, "SameSite", a.GetAttributes()[0].GetName())
		assert.Equal(t, "Lax", a.GetAttributes()[0].GetValue())
		assert.Equal(t, "Secure", a.GetAttributes()[1].GetName())
		assert.Equal(t, time.Hour, out.hashPolicies[1].GetCookie().GetTtl().AsDuration())
	})

	t.Run("invalid cookie ttl", func(t *testing.T) {
		out := &trafficPolicySpecIr{}
		err := constructConsistentHash(kgateway.TrafficPolicySpec{ConsistentHash: &kgateway.ConsistentHash{
			Cookies: []kgateway.ConsistentHashCookie{{Name: "a", TTL: ptr.To("bogus")}},
		}}, out)
		assert.Error(t, err)
	})
}

func TestApplyConsistentHash(t *testing.T) {
	action := &envoyroutev3.RouteAction{HashPolicy: []*envoyroutev3.RouteAction_HashPolicy{headerHP("x", false)}}
	applyConsistentHash(&consistentHashIR{disable: true}, action)
	assert.Empty(t, action.GetHashPolicy())

	ch := &consistentHashIR{headers: []*envoyroutev3.RouteAction_HashPolicy{headerHP("y", false)}}
	ch.finalize()
	applyConsistentHash(ch, action)
	assertHashPolicies(t, []*envoyroutev3.RouteAction_HashPolicy{headerHP("y", false)}, action.GetHashPolicy())
}

func TestMergeConsistentHash(t *testing.T) {
	p2Ref := &ir.AttachedPolicyRef{Group: "gateway.kgateway.dev", Kind: "TrafficPolicy", Namespace: "ns", Name: "p2"}

	newPolicy := func(t *testing.T, in *kgateway.ConsistentHash) *TrafficPolicy {
		return &TrafficPolicy{spec: trafficPolicySpecIr{consistentHash: constructConsistentHashForTest(t, in)}}
	}

	t.Run("union with higher priority first", func(t *testing.T) {
		p1 := newPolicy(t, &kgateway.ConsistentHash{
			Headers:         []kgateway.ConsistentHashHeader{{HeaderName: "x-a"}, {HeaderName: "x-shared", Terminal: ptr.To(true)}},
			QueryParameters: []kgateway.ConsistentHashQueryParameter{{Name: "q"}},
		})
		p2 := newPolicy(t, &kgateway.ConsistentHash{
			Cookies:  []kgateway.ConsistentHashCookie{{Name: "c"}},
			Headers:  []kgateway.ConsistentHashHeader{{HeaderName: "X-Shared"}, {HeaderName: "x-b"}},
			SourceIP: &kgateway.ConsistentHashSourceIP{},
		})
		p2Orig := p2.spec.consistentHash.hashPolicies

		origins := ir.MergeOrigins{}
		MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: policy.AugmentedShallowMerge}, origins, TrafficPolicyMergeOpts{})

		assertHashPolicies(t, []*envoyroutev3.RouteAction_HashPolicy{
			headerHP("x-a", false),
			headerHP("x-shared", true),
			headerHP("x-b", false),
			cookieHP("c"),
			queryHP("q"),
		}, p1.spec.consistentHash.hashPolicies)
		assert.Equal(t, []string{"gateway.kgateway.dev/TrafficPolicy/ns/p2"}, origins.Get("consistentHash"))
		assert.True(t, hashPoliciesEqual(p2Orig, p2.spec.consistentHash.hashPolicies), "p2 must not be modified")
	})

	t.Run("overridable prefers p2", func(t *testing.T) {
		p1 := newPolicy(t, &kgateway.ConsistentHash{
			Headers:  []kgateway.ConsistentHashHeader{{HeaderName: "x-shared"}},
			SourceIP: &kgateway.ConsistentHashSourceIP{},
		})
		p2 := newPolicy(t, &kgateway.ConsistentHash{
			Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x-b"}, {HeaderName: "x-shared", Terminal: ptr.To(true)}},
		})
		MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: policy.OverridableDeepMerge}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})

		assertHashPolicies(t, []*envoyroutev3.RouteAction_HashPolicy{
			headerHP("x-b", false),
			headerHP("x-shared", true),
		}, p1.spec.consistentHash.hashPolicies)
	})

	t.Run("p1 unset takes p2", func(t *testing.T) {
		p1 := &TrafficPolicy{}
		p2 := newPolicy(t, &kgateway.ConsistentHash{})
		origins := ir.MergeOrigins{}
		MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: policy.AugmentedShallowMerge}, origins, TrafficPolicyMergeOpts{})
		assert.Same(t, p2.spec.consistentHash, p1.spec.consistentHash)
		assert.Equal(t, []string{"gateway.kgateway.dev/TrafficPolicy/ns/p2"}, origins.Get("consistentHash"))
	})

	t.Run("higher priority disable suppresses", func(t *testing.T) {
		p1 := newPolicy(t, &kgateway.ConsistentHash{Disable: ptr.To(true)})
		p2 := newPolicy(t, &kgateway.ConsistentHash{Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x"}}})
		MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: policy.AugmentedShallowMerge}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		assert.True(t, p1.spec.consistentHash.disable)
		assert.Empty(t, p1.spec.consistentHash.hashPolicies)
	})

	t.Run("overriding disable suppresses", func(t *testing.T) {
		p1 := newPolicy(t, &kgateway.ConsistentHash{Headers: []kgateway.ConsistentHashHeader{{HeaderName: "x"}}})
		p2 := newPolicy(t, &kgateway.ConsistentHash{Disable: ptr.To(true)})
		MergeTrafficPolicies(p1, p2, p2Ref, nil, policy.MergeOptions{Strategy: policy.OverridableShallowMerge}, ir.MergeOrigins{}, TrafficPolicyMergeOpts{})
		assert.True(t, p1.spec.consistentHash.disable)
	})
}
